<?php require 'header.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$action=$_POST['action']??'';if($action==='approve')db()->prepare('UPDATE reviews SET status="approved" WHERE id=?')->execute([$id]);if($action==='remove')db()->prepare('DELETE FROM reviews WHERE id=?')->execute([$id]);flash('success','Review updated.');header('Location: manage-reviews.php');exit;}$reviews=db()->query('SELECT r.*,p.name FROM reviews r JOIN products p ON p.id=r.product_id ORDER BY r.created_at DESC')->fetchAll();?><div class="admin-title"><p>CUSTOMER VOICE</p><h2>Manage reviews</h2></div><section class="admin-panel"><table><thead><tr><th>Customer</th><th>Product</th><th>Rating</th><th>Comment</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td><?=e($r['customer_name'])?></td><td><?=e($r['name'])?></td><td><?=$r['rating']?>/5</td><td><?=e($r['comment'])?></td><td><?=e($r['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><?php if($r['status']!=='approved'):?><button name="action" value="approve">Approve</button><?php endif?><button class="danger" name="action" value="remove">Remove</button></form></td></tr><?php endforeach?></tbody></table></section><?php require 'footer.php'; ?>
